import{_ as r,C as a,c as s,o as i,a3 as t,G as n}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Work centers","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/manufacturing/advanced-configuration/work-centers.md","filePath":"master/supply-chain/manufacturing/advanced-configuration/work-centers.md","lastUpdated":1791902625000}'),l={name:"master/supply-chain/manufacturing/advanced-configuration/work-centers.md"};function c(u,e,p,d,h,g){const o=a("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="work-centers" tabindex="-1">Work centers <a class="header-anchor" href="#work-centers" aria-label="Permalink to &quot;Work centers&quot;">​</a></h1><p>A work center is a place where production steps are carried out, such as a machine, an assembly table or a packing desk. It holds the data Aureus needs to plan work: when the place is open, how many units it handles at once, how efficient it is and what an hour of use costs.</p><blockquote><p><strong>In simple words:</strong> A work center is the &quot;where&quot; of a production step.</p></blockquote><p>Open <code>Manufacturing → Configurations → Work Centers</code>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Gate</p><p><strong>Work Centers</strong> is hidden until you turn on <strong>Work Orders</strong> in <code>Manufacturing → Settings → Manage Operations</code>. The option reads &quot;Execute operations at designated work centers.&quot;</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2>',7)),n(o,{src:"/images1/manufacturing/wc_list.png",alt:"Work Centers list with Assembly Station and Quality & Packing, all columns visible, tab All selected"}),e[1]||(e[1]=t('<ul><li><strong>Tabs:</strong> <strong>All</strong> and <strong>Archived</strong>.</li><li><strong>Columns:</strong> <strong>Name</strong>, <strong>Code</strong>, <strong>Company</strong>, <strong>Working Hours</strong>, <strong>Working State</strong>, <strong>Capacity</strong>, <strong>Efficiency</strong>. <strong>Cost per Hour</strong> can be shown from the column toggle.</li><li><strong>New Work Center:</strong> opens the create form.</li></ul><h2 id="create-a-work-center" tabindex="-1">Create a work center <a class="header-anchor" href="#create-a-work-center" aria-label="Permalink to &quot;Create a work center&quot;">​</a></h2><p>Scenario: the sample shop has <strong>Assembly Station</strong> (code MC-ASM, capacity 3, efficiency 85.80%) and <strong>Quality &amp; Packing</strong> (code MC-PCK, capacity 5, efficiency 92.46%). Both use the <strong>Standard 38 hours/week</strong> schedule.</p><ol><li>Open <code>Manufacturing → Configurations → Work Centers</code> and click <strong>New Work Center</strong>.</li></ol>',4)),n(o,{src:"/images1/manufacturing/wc_create_general.png",alt:"Create Work Center form filled for Assembly Station: Name, Code MC-ASM, Tag, Alternative Work Centers, Working Hours Standard 38 hours/week, Company, Description"}),e[2]||(e[2]=t('<h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong><em>Name:</em></strong> The title shown on work orders. Required.</li><li><strong><em>Code:</em></strong> A short reference, for example <code>MC-ASM</code>.</li><li><strong><em>Tag:</em></strong> Optional labels to group similar work centers.</li><li><strong><em>Alternative Work Centers:</em></strong> Other work centers that can do the same job. When planning, Aureus compares them with this one.</li><li><strong><em>Working Hours:</em></strong> The schedule that says when the work center is open. Required. Planning places work orders inside these hours.</li><li><strong><em>Company:</em></strong> The owning company.</li><li><strong><em>Description:</em></strong> Free notes for your team.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If a work center has no working hours calendar, planning fails with &quot;There is no defined calendar on work center&quot;.</p></div><h3 id="production-information" tabindex="-1">Production Information <a class="header-anchor" href="#production-information" aria-label="Permalink to &quot;Production Information&quot;">​</a></h3>',4)),n(o,{src:"/images1/manufacturing/wc_create_production.png",alt:"Production Information and Costing Information boxes filled for Assembly Station (Time Efficiency 85.80, Default Capacity 3, Setup Time, Cleanup Time, Cost per Hour)"}),e[3]||(e[3]=t('<ul><li><strong><em>Time Efficiency:</em></strong> A percentage up to 100. A lower value lengthens the planned time. At 80%, a 60 minute step is planned for 75 minutes.</li><li><strong><em>Default Capacity:</em></strong> How many units the work center makes in one cycle.</li><li><strong><em>Setup Time:</em></strong> Minutes to prepare before a run.</li><li><strong><em>Cleanup Time:</em></strong> Minutes to clean up after a run.</li></ul><h3 id="costing-information" tabindex="-1">Costing Information <a class="header-anchor" href="#costing-information" aria-label="Permalink to &quot;Costing Information&quot;">​</a></h3><ul><li><strong><em>Cost per Hour:</em></strong> What one hour of use costs. Aureus multiplies it by the expected hours to get the operation cost on the manufacturing order.</li></ul><h3 id="specific-capacity" tabindex="-1">Specific Capacity <a class="header-anchor" href="#specific-capacity" aria-label="Permalink to &quot;Specific Capacity&quot;">​</a></h3><p>Use this when one product needs different numbers from the default. Click <strong>Add a line</strong>.</p>',5)),n(o,{src:"/images1/manufacturing/wc_specific_capacity.png",alt:"Specific Capacity table with one line added for Business Laptop (UOM, Capacity, Setup Time, Cleanup Time)"}),e[4]||(e[4]=t(`<ul><li><strong><em>Product:</em></strong> The product the line applies to.</li><li><strong><em>UOM:</em></strong> Its unit of measure.</li><li><strong><em>Capacity:</em></strong> Units per cycle for this product.</li><li><strong><em>Setup Time</em> and <em>Cleanup Time:</em></strong> Minutes for this product. They replace the work center defaults.</li></ul><ol start="2"><li>Click <strong>Create</strong>. Use <strong>Create &amp; create another</strong> to add the next one.</li></ol><h2 id="how-the-expected-time-is-worked-out" tabindex="-1">How the expected time is worked out <a class="header-anchor" href="#how-the-expected-time-is-worked-out" aria-label="Permalink to &quot;How the expected time is worked out&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cycles   = units to make / capacity, rounded up</span></span>
<span class="line"><span>duration = setup + cleanup + cycles x step time x 100 / efficiency</span></span></code></pre></div><p>Example: 5 laptops at <strong>Assembly Station</strong> with capacity 3 make 2 cycles. With a 60 minute step and 85.80% efficiency, the cycles take about 140 minutes. Setup and cleanup are added on top.</p><h2 id="the-operations-sub-page" tabindex="-1">The Operations sub page <a class="header-anchor" href="#the-operations-sub-page" aria-label="Permalink to &quot;The Operations sub page&quot;">​</a></h2><p>Open a work center and click <strong>Operations</strong>. You see every routing step that runs here, and the <strong>New Operation</strong> button adds one with this work center already chosen. See <a href="./operations.html">Operations</a>.</p>`,7)),n(o,{src:"/images1/manufacturing/wc_operations_subpage.png",alt:"Assembly Station Operations sub page listing Assemble Components"}),e[5]||(e[5]=t('<h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>View</strong> and <strong>Edit</strong> show or change the record.</li><li><strong>Delete</strong> archives the work center. It moves to the <strong>Archived</strong> tab, with the message &quot;Work center archived&quot;.</li><li>On the <strong>Archived</strong> tab you can restore it or delete it for good.</li><li>A permanent delete is refused when the work center is in use: &quot;The work center cannot be deleted because it is currently in use.&quot;</li><li>The <strong>Working State</strong> column shows whether the work center is currently running work.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Give every work center a realistic efficiency. Planned dates for work orders depend on it.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./operations.html">Operations</a></li><li><a href="./../workflows/plan-and-schedule.html">Plan and schedule</a></li><li><a href="./../workflows/work-orders.html">Work orders</a></li><li><a href="./../basic-setup/manufacturing-order-costs.html">Manufacturing order costs</a></li></ul>',5))])}const k=r(l,[["render",c]]);export{f as __pageData,k as default};
